-- 夹具取自本机真实的 opencode.db 的**旧格式**表：session + message + part
-- （消息与片段分两张表；片段里的 type 是 text / tool / reasoning 等）。
create table session (id text primary key, project_id text, parent_id text, slug text, directory text, title text, version text, time_created integer, time_updated integer, agent text, model text);
create table message (id text primary key, session_id text, time_created integer, time_updated integer, data text);
create table part (id text primary key, message_id text, session_id text, time_created integer, time_updated integer, data text);
